  /* ---------------------------------------------------------
     SEARCH MATCHING
     Every search box used to do a plain substring test on the food
     name. That is why searching "egg" offered Eggplant, "oat" offered
     Goat Cheese and Goat Meat, "pea" offered Pear and Pearl Barley,
     "ham" offered Nuoc Cham and "bar" offered Barramundi — none of
     which contain the thing being searched for.

     Match on whole words instead, anchored to the start of a word, so
     "chick" still finds Chicken but "oat" can no longer find Goat.
     Plurals count as the same word, compound family names still work
     ("berries" finds Blueberries), and a short list of known
     look-alikes is blocked outright.
  --------------------------------------------------------- */
  function searchWords(text){
    let s = String(text == null ? '' : text).toLowerCase();
    if (s.normalize) s = s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    return s.split(/[^a-z0-9]+/).filter(Boolean);
  }

  /* "peas" and "pea", "berries" and "berry" are the same search */
  function searchSingular(w){
    if (w.length > 4 && /ies$/.test(w))                     return w.slice(0,-3) + 'y';
    if (w.length > 4 && /(ses|xes|zes|ches|shes)$/.test(w)) return w.slice(0,-2);
    if (w.length > 3 && /s$/.test(w) && !/ss$/.test(w))     return w.slice(0,-1);
    return w;
  }

  /* Words that start or end like a search term but are a completely
     different food. Typing the full word still finds them. */
  const SEARCH_LOOKALIKES = {
    egg:   ['eggplant','eggplants'],
    pea:   ['pear','pears','pearl','peach','peaches','peanut','peanuts'],
    pear:  ['pearl'],
    bar:   ['barramundi','barley','bartlett'],
    corn:  ['cornish','acorn'],
    oat:   ['goat'],
    nut:   ['nutmeg','nutritional','butternut','donut','doughnut'],
    ham:   ['hamburger'],
    bean:  ['beansprout'],
  };

  /* Foods whose family name lives on the end of a compound word.
     "berries" should still find Blueberries and "nuts" should still
     find Walnuts — but this is a fixed list, so "apple" never reaches
     Pineapple and "egg" never reaches Eggplant. */
  const SEARCH_FAMILIES = ['berry','melon','nut','fish','pepper','seed','bean',
                           'pea','corn','milk','cake','bread','noodle','fruit','root'];

  function wordMatchesTerm(word, term){
    if (word === term) return true;
    const wS = searchSingular(word), tS = searchSingular(term);
    if (wS === tS) return true;

    const blocked = SEARCH_LOOKALIKES[term] || SEARCH_LOOKALIKES[tS] || [];
    if (blocked.includes(word) || blocked.includes(wS)) return false;

    // a deliberate prefix: "chick" -> Chicken, "avo" -> Avocado
    if (term.length >= 3 && word.startsWith(term)) return true;
    // a family name on the end of a compound: "berries" -> Blueberries
    if (SEARCH_FAMILIES.includes(tS) && wS.length > tS.length && wS.endsWith(tS)) return true;
    return false;
  }

  /* Every word typed has to land somewhere in the name, so
     "chicken thigh" finds the thigh and not every bird on the list. */
  function matchesQuery(text, query){
    const terms = searchWords(query);
    if (!terms.length) return true;
    const words = searchWords(text);
    if (!words.length) return false;
    return terms.every(t => words.some(w => wordMatchesTerm(w, t)));
  }

  /* Last resort only: if the strict pass found nothing at all, fall back
     to the old loose test rather than leaving someone stranded. This can
     only ever add results to an empty list. */
  function looseMatchesQuery(text, query){
    const q = String(query || '').trim().toLowerCase();
    return !!q && String(text || '').toLowerCase().includes(q);
  }

  /* Filter a list of foods by a typed query, strictly, with the loose
     pass used only when strict comes back empty. */
  function searchFoods(list, query, extra){
    const keep = extra || (()=>true);
    const pool = list.filter(keep);
    const q = String(query || '').trim();
    if (!q) return pool;
    const strict = pool.filter(f => matchesQuery(f.name, q));
    if (strict.length) return strict;
    return pool.filter(f => looseMatchesQuery(f.name, q));
  }

